            dirnames[:] = []
            continue
        if "__init__.py" in filenames and os.path.basename(dirpath) == "tabulate":
            f = os.path.join(dirpath, "__init__.py")
            found.append((f, os.path.getsize(f)))

print("FOUND:")
for f, s in found:
