print("=== SEARCH END ===")

import os
import sys

out = []
out.append("cwd: " + os.getcwd())
out.append("sys.path: " + repr(sys.path))
roots = set()
for p in sys.path:
    if p:
        roots.add(p)
try:
    import site
    roots.update(site.getsitepackages())
    try:
        roots.add(site.getusersitepackages())
    except Exception:
        pass
except Exception as e:
    out.append("site err " + repr(e))
roots.add(os.path.join(os.path.expanduser("~"), ".cache"))
roots.add("/tmp")
roots.add(os.path.expanduser("~"))
roots.add(os.getcwd())

found = []
cachehits = []
for root in roots:
    if not root or not os.path.isdir(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        depth = dirpath.count(os.sep) - root.count(os.sep)
        if depth > 8:
            dirnames[:] = []
            continue
        if "__init__.py" in filenames and os.path.basename(dirpath) == "tabulate":
            f = os.path.join(dirpath, "__init__.py")
            found.append((os.path.getsize(f), f))
        for fn in filenames:
            if "tabulate" in fn.lower():
                cachehits.append(os.path.join(dirpath, fn))

out.append("FOUND:")
for s, f in found:
    out.append("  %d  %s" % (s, f))
out.append("CACHEHITS:")
for c in cachehits:
    out.append("  " + c)

with open("_search_results.txt", "w", encoding="utf-8") as fh:
    fh.write("\n".join(out))

