    print("getusersitepackages err", e)

for p in paths:
    for root, dirs, files in os.walk(p):
        if 'furl' in root.lower() and 'furl.py' in files:
            print("FOUND:", os.path.join(root, 'furl.py'))

for cmd in [['pip', 'show', 'furl'], ['python', '-m', 'pip', 'show', 'furl']]:
    try:
        out = subprocess.check_output(cmd, stderr=subprocess.STDOUT)
        print("CMD", cmd, "=>")
        print(out.decode('utf8', 'replace'))
    except Exception as e:
        print("CMD", cmd, "err", e)

# Search whole filesystem (bounded) for other copies of furl.py
for base in ['/tmp', '/root', '/home', os.path.expanduser('~'), 'C:\\']:
    if not os.path.isdir(base):
        continue
    for root, dirs, files in os.walk(base):
        dirs[:] = [d for d in dirs if d not in ('.git', '__pycache__')]
        if root.count(os.sep) > 8:
            dirs[:] = []
        if 'furl.py' in files and os.path.abspath(root) != os.path.abspath(os.path.dirname(__file__)):
            print("COPY:", os.path.join(root, 'furl.py'))
print("==== EXPLORE END ====")

