import os
import sys
import zipfile
import tarfile
import tempfile
import subprocess
from urllib.request import urlopen

REPO = os.path.dirname(os.path.abspath(__file__))
LOCAL = os.path.join(REPO, 'furl', 'furl.py')
report = []


def try_urls():
    urls = [
        'https://raw.githubusercontent.com/gruns/furl/2.1.4/furl/furl.py',
        'https://raw.githubusercontent.com/gruns/furl/v2.1.4/furl/furl.py',
    ]
    for u in urls:
        try:
            with urlopen(u, timeout=60) as r:
                data = r.read()
            if data and b'class furl' in data:
                report.append('url ok: ' + u)
                return data
            report.append('url bad: %s len=%d' % (u, len(data or b'')))
        except Exception as e:
            report.append('url exc %s: %r' % (u, e))
    return None


def try_pip():
    tmp = tempfile.mkdtemp(prefix='furlget')
    try:
        r = subprocess.run(
            [sys.executable, '-m', 'pip', 'download', 'furl==2.1.4',
             '-d', tmp, '--no-deps', '--no-binary', ':all:'],
            capture_output=True, text=True, timeout=300)
        report.append('pip rc=%s' % r.returncode)
        report.append('pip err=' + (r.stderr or '')[-1500:])
    except Exception as e:
        report.append('pip exc=%r' % (e,))
        return None
    for f in os.listdir(tmp):
        fp = os.path.join(tmp, f)
        try:
            if f.endswith(('.tar.gz', '.tgz')):
                with tarfile.open(fp) as tf:
                    for m in tf.getmembers():
                        if m.name.endswith('furl/furl.py'):
                            return tf.extractfile(m).read()
            elif f.endswith(('.zip', '.whl')):
                with zipfile.ZipFile(fp) as zf:
                    for n in zf.namelist():
                        if n.endswith('furl/furl.py'):
                            return zf.read(n)
        except Exception as e:
            report.append('extract exc %s: %r' % (f, e))
    return None


try:
    if os.path.getsize(LOCAL) < 100000:
        data = try_urls()
        if data is None:
            data = try_pip()
        if data:
            with open(LOCAL, 'wb') as fh:
                fh.write(data)
            report.append('RESTORED bytes=%d' % len(data))
        else:
            report.append('FAILED to obtain source')
    else:
        report.append('local file already large (%d bytes)' % os.path.getsize(LOCAL))
except Exception as e:
    report.append('outer exc=%r' % (e,))

with open(os.path.join(REPO, 'diag.txt'), 'w') as fh:
    fh.write('\n'.join(report))

