import inspect
import furl.furl as fmod

P = getattr(fmod, 'Path', None)


def test_discover():
    out = []
    out.append('MODULE_NONSCHEME')
    for name in dir(fmod):
        if 'scheme' in name.lower():
            out.append('M:' + name)
    if P is not None:
        for name in dir(P):
            if 'scheme' in name.lower():
                out.append('P:' + name)
    raise AssertionError('|'.join(out))

def test_find():
    with open('furl/furl.py') as fh:
        lines = fh.readlines()
    marks = ['class Path', 'def add', 'def isabsolute', 'def _path',
             'def load', 'class furl', 'is_valid_scheme']
    out = []
    for i, l in enumerate(lines):
        for m in marks:
            if m in l:
                out.append('%d: %s' % (i, l.rstrip()))
    raise AssertionError('\n'.join(out))
